    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-2: #f8fafc;
        --text: #132238;
        --muted: #55667a;
        --border: #d7e0ea;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --error: #b42318;
        --success: #067647;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 30%),
          radial-gradient(circle at top right, rgba(14, 165, 233, 0.14), transparent 28%),
          var(--bg);
        line-height: 1.5;
      }

      a {
        color: var(--accent);
      }

      a:hover {
        color: var(--accent-strong);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--surface);
        color: var(--text);
        box-shadow: var(--shadow);
        transform: translateY(-180%);
        transition: transform 0.18s ease;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .page-card {
        width: min(100%, 68rem);
        display: grid;
        grid-template-columns: 1.05fr 0.95fr;
        gap: 1.5rem;
        align-items: stretch;
      }

      .hero,
      .panel {
        border: 1px solid rgba(215, 224, 234, 0.9);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.9);
        backdrop-filter: blur(10px);
        box-shadow: var(--shadow);
      }

      .hero {
        padding: 2.25rem;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 1.5rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.03em;
      }

      .hero p {
        margin: 0;
        max-width: 36rem;
        font-size: 1.05rem;
        color: var(--muted);
      }

      .trust-row {
        display: grid;
        gap: 0.75rem;
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .trust-item {
        padding: 1rem 1.05rem;
        border-radius: 1rem;
        background: var(--surface-2);
        border: 1px solid var(--border);
      }

      .trust-item strong {
        display: block;
        margin-bottom: 0.2rem;
        font-size: 0.95rem;
      }

      .trust-item span {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .panel {
        padding: 1.5rem;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      .field-label {
        font-weight: 600;
      }

      .required-mark {
        color: var(--error);
      }

      input {
        width: 100%;
        appearance: none;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        padding: 0.9rem 1rem;
        font: inherit;
        color: var(--text);
        background: #fff;
        transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
      }

      input::placeholder {
        color: #8a97a8;
      }

      input:hover {
        border-color: #a7b6c8;
      }

      input:focus-visible,
      button:focus-visible,
      .skip-link:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 2px;
        border-color: var(--accent);
      }

      .field-help,
      .field-error,
      .form-status {
        margin: 0;
        font-size: 0.92rem;
      }

      .field-help {
        color: var(--muted);
      }

      .field-error {
        color: var(--error);
        font-weight: 600;
      }

      .field-error[hidden] {
        display: none;
      }

      .form-status {
        min-height: 1.25rem;
        color: var(--success);
        font-weight: 600;
      }

      button {
        margin-top: 0.5rem;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.25rem;
        font: inherit;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        box-shadow: 0 14px 30px rgba(37, 99, 235, 0.28);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.02);
      }

      footer {
        margin-top: 1rem;
        color: var(--muted);
        font-size: 0.9rem;
        text-align: center;
      }

      @media (max-width: 900px) {
        .page-card {
          grid-template-columns: 1fr;
        }
      }

      @media (max-width: 640px) {
        .page-shell {
          padding: 0.75rem;
        }

        .hero,
        .panel {
          padding: 1.25rem;
          border-radius: 1.25rem;
        }

        .trust-row {
          grid-template-columns: 1fr;
        }
      }

      @media (forced-colors: active) {
        .hero,
        .panel,
        .trust-item,
        input,
        button {
          forced-color-adjust: auto;
          border: 1px solid CanvasText;
        }

        .skip-link:focus,
        input:focus-visible,
        button:focus-visible {
          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        status: "",
      };

      const fieldMeta = {
        fullName: {
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Jane Doe",
        },
        email: {
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "jane@company.com",
        },
        phone: {
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          help: "Optional. Enter a number in international format, like +1 555 123 4567.",
        },
      };

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (char) => ({
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;",
        })[char]);

      const fieldId = (name) => `field-${name}`;
      const helpId = (name) => `${fieldId(name)}-help`;
      const errorId = (name) => `${fieldId(name)}-error`;

      function renderField(name) {
        const meta = fieldMeta[name];
        const value = escapeHtml(state.values[name]);
        const hasError = Boolean(state.errors[name]);
        const describedBy = [meta.help ? helpId(name) : "", hasError ? errorId(name) : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label class="field-label" for="${fieldId(name)}">
              ${escapeHtml(meta.label)}
              ${meta.required ? '<span class="required-mark" aria-hidden="true"> *</span>' : ""}
            </label>
            <input
              id="${fieldId(name)}"
              name="${name}"
              type="${meta.type}"
              value="${value}"
              ${meta.autocomplete ? `autocomplete="${meta.autocomplete}"` : ""}
              ${meta.required ? "required" : ""}
              ${meta.placeholder ? `placeholder="${escapeHtml(meta.placeholder)}"` : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${hasError ? 'aria-invalid="true"' : ""}
            />
            ${meta.help ? `<p id="${helpId(name)}" class="field-help">${escapeHtml(meta.help)}</p>` : ""}
            <p id="${errorId(name)}" class="field-error" ${hasError ? "" : "hidden"}>${hasError ? escapeHtml(state.errors[name]) : ""}</p>
          </div>
        `;
      }

      function renderApp() {
        return `
          <header></header>
          <main id="maincontent" tabindex="-1" class="page-shell">
            <div class="page-card">
              <section class="hero" aria-labelledby="support-heading">
                <div>
                  <p class="eyebrow">Support</p>
                  <h1 id="support-heading">Contact our support team</h1>
                  <p>Send us a message and we’ll route it to the right person. Use the form for product questions, account help, or billing issues.</p>
                </div>
                <div class="trust-row" aria-label="What to expect">
                  <div class="trust-item">
                    <strong>Fast reply</strong>
                    <span>We usually respond within one business day.</span>
                  </div>
                  <div class="trust-item">
                    <strong>Direct help</strong>
                    <span>Your request goes straight to the support queue.</span>
                  </div>
                </div>
              </section>

              <section class="panel" aria-labelledby="form-heading">
                <h2 id="form-heading">Send a message</h2>
                <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>
                <p id="form-status" class="form-status" role="status" aria-live="polite">${escapeHtml(state.status)}</p>

                <form id="support-form" novalidate>
                  ${renderField("fullName")}
                  ${renderField("email")}
                  ${renderField("phone")}
                  <button type="submit">Send message</button>
                </form>
              </section>
            </div>
          </main>
          <footer>Need something urgent? Call our published support line for immediate assistance.</footer>
        `;
      }

      function validate(values) {
        const errors = {};
        const fullName = values.fullName.trim();
        const email = values.email.trim();
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        if (!fullName) {
          errors.fullName = "Error: Enter your full name.";
        }

        if (!email) {
          errors.email = "Error: Enter your email address.";
        } else if (!emailPattern.test(email)) {
          errors.email = "Error: Enter a valid email address, like name@example.com.";
        }

        return errors;
      }

      function syncField(name) {
        const input = document.getElementById(fieldId(name));
        const error = document.getElementById(errorId(name));
        const meta = fieldMeta[name];
        const hasError = Boolean(state.errors[name]);
        const describedBy = [meta.help ? helpId(name) : "", hasError ? errorId(name) : ""].filter(Boolean).join(" ");

        if (input) {
          input.value = state.values[name];
          input.toggleAttribute("aria-invalid", hasError);
          if (hasError) {
            input.setAttribute("aria-invalid", "true");
          }
          if (describedBy) {
            input.setAttribute("aria-describedby", describedBy);
          } else {
            input.removeAttribute("aria-describedby");
          }
        }

        if (error) {
          error.textContent = hasError ? state.errors[name] : "";
          error.toggleAttribute("hidden", !hasError);
        }
      }

      function syncStatus() {
        const status = document.getElementById("form-status");
        if (status) {
          status.textContent = state.status;
        }
      }

      function render() {
        document.getElementById("app").innerHTML = renderApp();
      }

      function clearFieldError(name) {
        if (state.errors[name]) {
          delete state.errors[name];
          syncField(name);
        }
      }

      document.getElementById("app").innerHTML = renderApp();

      document.getElementById("app").addEventListener("input", (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) return;
        if (!(target.name in state.values)) return;

        state.values[target.name] = target.value;
        state.status = "";
        syncStatus();
        clearFieldError(target.name);
      });

      document.getElementById("app").addEventListener("submit", (event) => {
        const form = event.target;
        if (!(form instanceof HTMLFormElement)) return;

        event.preventDefault();
        state.values.fullName = form.fullName.value;
        state.values.email = form.email.value;
        state.values.phone = form.phone.value;
        state.errors = validate(state.values);
        state.status = "";

        ["fullName", "email", "phone"].forEach(syncField);
        syncStatus();

        const firstErrorName = Object.keys(state.errors)[0];
        if (firstErrorName) {
          const firstErrorInput = document.getElementById(fieldId(firstErrorName));
          state.status = "Please fix the highlighted fields and try again.";
          syncStatus();
          if (firstErrorInput) {
            firstErrorInput.focus();
          }
          return;
        }

        state.status = "Thanks — your message has been sent to support.";
        syncStatus();
        form.reset();
        state.values = { fullName: "", email: "", phone: "" };
        ["fullName", "email", "phone"].forEach(syncField);
      });

      window.addEventListener("load", () => {
        const main = document.getElementById("maincontent");
        if (main) {
          main.focus({ preventScroll: true });
        }
      });
    </script>
  </body>
</html>
