  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        status: "",
      };

      const fieldMeta = {
        fullName: {
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Jane Doe",
        },
        email: {
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "jane@company.com",
        },
        phone: {
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          help: "Optional. Enter a number in international format, like +1 555 123 4567.",
        },
      };

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (char) => ({
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;",
        })[char]);

      const fieldId = (name) => `field-${name}`;
      const helpId = (name) => `${fieldId(name)}-help`;
      const errorId = (name) => `${fieldId(name)}-error`;

      function renderField(name) {
        const meta = fieldMeta[name];
        const value = escapeHtml(state.values[name]);
        const hasError = Boolean(state.errors[name]);
        const describedBy = [meta.help ? helpId(name) : "", hasError ? errorId(name) : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label class="field-label" for="${fieldId(name)}">
              ${escapeHtml(meta.label)}
              ${meta.required ? '<span class="required-mark" aria-hidden="true"> *</span>' : ""}
            </label>
            <input
              id="${fieldId(name)}"
              name="${name}"
              type="${meta.type}"
              value="${value}"
              ${meta.autocomplete ? `autocomplete="${meta.autocomplete}"` : ""}
              ${meta.required ? "required" : ""}
              ${meta.placeholder ? `placeholder="${escapeHtml(meta.placeholder)}"` : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${hasError ? 'aria-invalid="true"' : ""}
            />
            ${meta.help ? `<p id="${helpId(name)}" class="field-help">${escapeHtml(meta.help)}</p>` : ""}
            <p id="${errorId(name)}" class="field-error" ${hasError ? "" : "hidden"}>${hasError ? escapeHtml(state.errors[name]) : ""}</p>
          </div>
        `;
      }

      function renderApp() {
        return `
          <main id="maincontent" tabindex="-1" class="page-shell">
            <div class="page-card">
              <section class="hero" aria-labelledby="support-heading">
                <div>
                  <p class="eyebrow">Support</p>
                  <h1 id="support-heading">Contact our support team</h1>
                  <p>Send us a message and we’ll route it to the right person. Use the form for product questions, account help, or billing issues.</p>
                </div>
                <div class="trust-row" aria-label="What to expect">
                  <div class="trust-item">
                    <strong>Fast reply</strong>
                    <span>We usually respond within one business day.</span>
                  </div>
                  <div class="trust-item">
                    <strong>Direct help</strong>
                    <span>Your request goes straight to the support queue.</span>
                  </div>
                </div>
              </section>

              <section class="panel" aria-labelledby="form-heading">
                <h2 id="form-heading">Send a message</h2>
                <p class="form-note">Fields marked with <span aria-hidden="true">*</span> are required.</p>
                <p id="form-status" class="form-status" role="status" aria-live="polite">${escapeHtml(state.status)}</p>

                <form id="support-form" novalidate>
                  ${renderField("fullName")}
                  ${renderField("email")}
                  ${renderField("phone")}
                  <button type="submit">Send message</button>
                </form>
              </section>
            </div>
          </main>
          <footer>Need something urgent? Call our published support line for immediate assistance.</footer>
        `;
      }

      function validate(values) {
        const errors = {};
        const fullName = values.fullName.trim();
        const email = values.email.trim();
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        if (!fullName) {
          errors.fullName = "Error: Enter your full name.";
        }

        if (!email) {
          errors.email = "Error: Enter your email address.";
        } else if (!emailPattern.test(email)) {
          errors.email = "Error: Enter a valid email address, like name@example.com.";
        }

        return errors;
      }

      function syncField(name) {
        const input = document.getElementById(fieldId(name));
        const error = document.getElementById(errorId(name));
        const meta = fieldMeta[name];
        const hasError = Boolean(state.errors[name]);
        const describedBy = [meta.help ? helpId(name) : "", hasError ? errorId(name) : ""].filter(Boolean).join(" ");

        if (input) {
          input.value = state.values[name];
          input.toggleAttribute("aria-invalid", hasError);
          if (hasError) {
            input.setAttribute("aria-invalid", "true");
          }
          if (describedBy) {
            input.setAttribute("aria-describedby", describedBy);
          } else {
            input.removeAttribute("aria-describedby");
          }
        }

        if (error) {
          error.textContent = hasError ? state.errors[name] : "";
          error.toggleAttribute("hidden", !hasError);
        }
      }

      function syncStatus() {
        const status = document.getElementById("form-status");
        if (status) {
          status.textContent = state.status;
        }
      }

      function clearFieldError(name) {
        if (state.errors[name]) {
          delete state.errors[name];
          syncField(name);
        }
      }

      document.getElementById("app").innerHTML = renderApp();

      document.getElementById("app").addEventListener("input", (event) => {
        const target = event.target;
        if (!(target instanceof HTMLInputElement)) return;
        if (!(target.name in state.values)) return;

        state.values[target.name] = target.value;
        state.status = "";
        syncStatus();
        clearFieldError(target.name);
      });

      document.getElementById("app").addEventListener("submit", (event) => {
        const form = event.target;
        if (!(form instanceof HTMLFormElement)) return;

        event.preventDefault();
        state.values.fullName = form.elements.namedItem("fullName").value;
        state.values.email = form.elements.namedItem("email").value;
        state.values.phone = form.elements.namedItem("phone").value;
        state.errors = validate(state.values);
        state.status = "";

        ["fullName", "email", "phone"].forEach(syncField);
        syncStatus();

        const firstErrorName = Object.keys(state.errors)[0];
        if (firstErrorName) {
          const firstErrorInput = document.getElementById(fieldId(firstErrorName));
          state.status = "Please fix the highlighted fields and try again.";
          syncStatus();
          if (firstErrorInput) {
            firstErrorInput.focus();
          }
          return;
        }

        state.status = "Thanks — your message has been sent to support.";
        syncStatus();
        form.reset();
        state.values = { fullName: "", email: "", phone: "" };
        ["fullName", "email", "phone"].forEach(syncField);
      });
    </script>
  </body>
</html>
