        email: {
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "jane@company.com",
        },
        phone: {
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          help: "Optional. Enter a number in international format, like +1 555 123 4567.",
        },
      };

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (char) => ({
          "&": "&amp;",
          "<": "&lt;",
          ">": "&gt;",
          '"': "&quot;",
          "'": "&#39;",
        })[char]);

      const fieldId = (name) => `field-${name}`;
      const helpId = (name) => `${fieldId(name)}-help`;
      const errorId = (name) => `${fieldId(name)}-error`;

      function renderField(name) {
        const meta = fieldMeta[name];
        const value = escapeHtml(state.values[name]);
        const hasError = Boolean(state.errors[name]);
        const describedBy = [meta.help ? helpId(name) : "", hasError ? errorId(name) : ""].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label class="field-label" for="${fieldId(name)}">
              ${escapeHtml(meta.label)}
              ${meta.required ? '<span class="required-mark" aria-hidden="true"> *</span>' : ""}
            </label>
            <input
              id="${fieldId(name)}"
              name="${name}"
              type="${meta.type}"
              value="${value}"
              ${meta.autocomplete ? `autocomplete="${meta.autocomplete}"` : ""}
              ${meta.required ? "required" : ""}
              ${meta.placeholder ? `placeholder="${escapeHtml(meta.placeholder)}"` : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${hasError ? 'aria-invalid="true"' : ""}
            />
            ${meta.help ? `<p id="${helpId(name)}" class="field-help">${escapeHtml(meta.help)}</p>` : ""}
            <p id="${errorId(name)}" class="field-error" ${hasError ? "" : "hidden"}>${hasError ? escapeHtml(state.errors[name]) : ""}</p>
          </div>
        `;
      }

      function renderApp() {
        return `
          <main id="maincontent" tabindex="-1" class="page-shell">
            <div class="page-card">
              <section class="hero" aria-labelledby="support-heading">
                <div>
                  <p class="eyebrow">Support</p>
