  if (initial.requiredCount !== 2) {
    throw new Error(`expected 2 required inputs, found ${initial.requiredCount}`);
  }
  if (!initial.helpText) {
    throw new Error('missing phone helper text');
  }

  await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });
