const path = require('path');
const { pathToFileURL } = require('url');
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const url = pathToFileURL(path.resolve('index.html')).href;
  await page.goto(url, { waitUntil: 'load' });

  const before = await page.evaluate(() => ({
    mainTag: document.querySelector('main')?.tagName,
    h1Count: document.querySelectorAll('h1').length,
    required: [...document.querySelectorAll('input')].filter((el) => el.required).length,
    inlineErrors: [...document.querySelectorAll('.field-error')].map((el) => ({ hidden: el.hidden, text: el.textContent.trim() })),
  }));

  if (before.mainTag !== 'MAIN' || before.h1Count !== 1 || before.required !== 2 || before.inlineErrors.some((e) => !e.hidden || e.text)) {
    throw new Error('initial accessibility/markup checks failed');
  }

  await page.addScriptTag({ path: require.resolve('axe-core/axe.min.js') });
  const axe = await page.evaluate(async () => await window.axe.run());
  const violations = axe.violations.filter((v) => !v.tags.includes('best-practice'));
  if (violations.length) {
    throw new Error(JSON.stringify(violations.map((v) => v.id)));
  }

  await page.fill('#field-fullName', 'Ada Lovelace');
  await page.fill('#field-email', 'not-an-email');
  await page.click('button[type="submit"]');
  const afterInvalid = await page.evaluate(() => ({
    activeId: document.activeElement.id,
    emailInvalid: document.querySelector('#field-email')?.getAttribute('aria-invalid'),
    emailError: document.querySelector('#field-email-error')?.textContent.trim(),
    status: document.querySelector('#form-status')?.textContent.trim(),
  }));
  if (afterInvalid.activeId !== 'field-email' || afterInvalid.emailInvalid !== 'true' || !afterInvalid.emailError.startsWith('Error:') || !afterInvalid.status) {
    throw new Error('invalid-submit behavior failed');
  }

  await page.fill('#field-email', 'ada@example.com');
  await page.click('button[type="submit"]');
  const afterValid = await page.evaluate(() => ({
    status: document.querySelector('#form-status')?.textContent.trim(),
    fullName: document.querySelector('#field-fullName')?.value,
    email: document.querySelector('#field-email')?.value,
    phone: document.querySelector('#field-phone')?.value,
  }));
  if (!afterValid.status.includes('sent') || afterValid.fullName !== '' || afterValid.email !== '' || afterValid.phone !== '') {
    throw new Error('submit reset behavior failed');
  }

  await browser.close();
  console.log('tests-ok');
})().catch((error) => {
  console.error(error.message || error);
